import { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import { usesPerformanceToolTimePeriod } from 'domain/Filter';
import { FilterDataStructure, FilterForm } from 'models/Filters';
import { setPerformanceToolVolumeChartPeriodType } from 'redux/slices/filters';
import { selectPage } from 'redux/slices/filters/selectors';
import { RootState } from 'redux/types';
import { resolveTimePeriodSelection } from 'utils/timePeriod/timePeriodAvailability';

import { PERFORMANCE_TOOL_PAGE_NAME } from '../../../constants';
import { BigNumbersSectionData } from '../../../types';
import {
  getCanonicalPerformanceToolTimePeriodType,
  getPerformanceToolRequestPeriodType,
  getVolumeBigNumbersApiPeriodType,
  getVolumeBigNumbersCardPeriodType,
  getVolumeBigNumbersSelectedCardIndex,
} from '../../../utils';

interface UseKpiDrillDownTimePeriodParams {
  applied: FilterForm;
  appliedDataFilters: FilterDataStructure;
  kpiSlug: string;
  kpiGroupDtEnd?: string;
}

export const useKpiDrillDownTimePeriod = ({
  applied,
  appliedDataFilters,
  kpiSlug,
  kpiGroupDtEnd,
}: UseKpiDrillDownTimePeriodParams) => {
  const dispatch = useDispatch();
  const timePeriodApplyToken = useSelector(
    (state: RootState) =>
      selectPage(PERFORMANCE_TOOL_PAGE_NAME)(state)
        ?.performanceToolVolumeTimePeriodApplyToken ?? 0,
  );
  const [selectedCardPeriodType, setSelectedCardPeriodType] = useState<
    string | null
  >(null);
  const usesTimePeriod = usesPerformanceToolTimePeriod(appliedDataFilters);
  const timePeriodSelection = usesTimePeriod
    ? resolveTimePeriodSelection(
        applied.period_type,
        applied.dt_end,
        kpiGroupDtEnd,
      )
    : null;
  const requestPeriodType =
    getPerformanceToolRequestPeriodType(timePeriodSelection);
  const hasInvalidTimePeriod = usesTimePeriod && !requestPeriodType;

  useEffect(() => {
    setSelectedCardPeriodType(null);
  }, [
    applied.dt_end,
    applied.period_type,
    requestPeriodType,
    timePeriodApplyToken,
  ]);

  const apiPeriodType = useMemo(() => {
    if (!requestPeriodType) return null;
    if (usesTimePeriod && selectedCardPeriodType) {
      return (
        getVolumeBigNumbersApiPeriodType(
          selectedCardPeriodType,
          applied.period_type,
        ) ?? requestPeriodType
      );
    }
    return requestPeriodType;
  }, [
    applied.period_type,
    requestPeriodType,
    selectedCardPeriodType,
    usesTimePeriod,
  ]);

  const activeCardPeriodType = useMemo(() => {
    if (!usesTimePeriod || !requestPeriodType) return null;
    return (
      selectedCardPeriodType ??
      getVolumeBigNumbersCardPeriodType(requestPeriodType, applied.dt_end)
    );
  }, [
    applied.dt_end,
    requestPeriodType,
    selectedCardPeriodType,
    usesTimePeriod,
  ]);

  useEffect(() => {
    if (!usesTimePeriod) {
      dispatch(setPerformanceToolVolumeChartPeriodType({ periodType: null }));
      return;
    }
    dispatch(
      setPerformanceToolVolumeChartPeriodType({
        periodType: activeCardPeriodType,
      }),
    );
    return () => {
      dispatch(setPerformanceToolVolumeChartPeriodType({ periodType: null }));
    };
  }, [activeCardPeriodType, dispatch, usesTimePeriod]);

  const legacyPeriodFilters = usesTimePeriod
    ? {}
    : { timeframe: applied.periods, period_type: applied.periods };
  const lineChartPeriodType =
    getCanonicalPerformanceToolTimePeriodType(apiPeriodType) ??
    applied.period_type;

  const getSelectedCardIndex = useCallback(
    (
      cards: BigNumbersSectionData[] | null | undefined,
      periodValues: string[],
    ) => {
      if (usesTimePeriod) {
        return getVolumeBigNumbersSelectedCardIndex(
          cards ?? undefined,
          activeCardPeriodType,
        );
      }
      return Math.max(periodValues.indexOf(applied.periods as string), 0);
    },
    [activeCardPeriodType, applied.periods, usesTimePeriod],
  );

  const selectCardPeriod = useCallback(
    (
      index: number,
      cards: BigNumbersSectionData[] | null | undefined,
      periodValues: string[],
      onLegacyPeriodChange: (period: string) => void,
    ) => {
      const card = cards?.[index];
      if (!card) return;
      if (usesTimePeriod) {
        setSelectedCardPeriodType(card.period_type ?? null);
        return;
      }
      const period = periodValues[index];
      if (period) onLegacyPeriodChange(period);
    },
    [usesTimePeriod],
  );

  return {
    usesTimePeriod,
    timePeriodSelection,
    requestPeriodType,
    hasInvalidTimePeriod,
    apiPeriodType,
    activeCardPeriodType,
    legacyPeriodFilters,
    lineChartPeriodType,
    lineChartDtEnd: applied.dt_end,
    lineChartCutoffDate: kpiGroupDtEnd,
    getSelectedCardIndex,
    selectCardPeriod,
  };
};
